import ast, copy, hashlib, json, math
from pathlib import Path
w=Path('/workspace'); r=json.load(open('/tmp/runtime_contract.json')); p=json.loads((w/'proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 if typ:
  expected={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int}[typ]
  assert isinstance(value,expected), (path,'type')
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,x in enumerate(value): validate(x,schema.get('items',{}),path+f'[{i}]')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'required')
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra')
  for k,v in value.items():
   if k in schema.get('properties',{}): validate(v,schema['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial']==r['context']['incumbent']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert r['phase']=='propose' and r['context']['previous_runtime_error'] is None
assert len(p['variants'])==4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len({v['file'] for v in p['variants']})==4
assert len(p['knowledge_assessments'])==15
assert {a['knowledge_id'] for a in p['knowledge_assessments']}==set(r['context']['latest_knowledge_usage']['retrieved_ids'])
base=ast.parse((w/'history_g2_r0069_summary_global.py').read_text())
def methods(tree):
 return {n.name:n for n in next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model').body if isinstance(n,ast.FunctionDef)}
def dump(n): return ast.dump(n,include_attributes=False)
bm=methods(base)
new_names={'evaluation_coefficient_layout','evaluation_pool_reduction'}
class Train(ast.NodeTransformer):
 def visit_If(self,node):
  node=self.generic_visit(node)
  # Only fold branches whose boolean value is settled by training=True.
  def truth(n):
   if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name) and n.value.id=='self' and n.attr=='training': return True
   if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.Not):
    x=truth(n.operand); return None if x is None else not x
   if isinstance(n,ast.BoolOp) and isinstance(n.op,ast.And):
    ts=[truth(x) for x in n.values]
    return False if False in ts else (True if all(t is True for t in ts) else None)
   return None
  t=truth(node.test)
  return node.body if t is True else node.orelse if t is False else node
class StripNewInit(ast.NodeTransformer):
 def visit_FunctionDef(self,node):
  pairs=list(zip(node.args.args[-len(node.args.defaults):],node.args.defaults))
  prefix=node.args.args[:-len(node.args.defaults)]
  node.args.args=prefix+[a for a,d in pairs if a.arg not in new_names]
  node.args.defaults=[d for a,d in pairs if a.arg not in new_names]
  node.body=[s for s in node.body if not ((isinstance(s,ast.If) and any(isinstance(n,ast.Name) and n.id in new_names for n in ast.walk(s.test))) or (isinstance(s,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr in new_names for t in s.targets)))]
  return node
helper_names=['_RankAffine','_PartitionedAffine','_ContextAffine']
parent_cfg=None
for n in base.body:
 if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): parent_cfg=ast.literal_eval(n.value)
for v in p['variants']:
 assert v['file']==Path(v['file']).name and v['file'].endswith('.py')
 src=(w/v['file']).read_text(); tree=ast.parse(src); compile(src,v['file'],'exec')
 cfg=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert cfg==v['config']
 assert {k:val for k,val in cfg.items() if k not in new_names}==parent_cfg
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(x.name.split('.')[0] in {'torch','unirank'} for x in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in {'torch','unirank'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','exec','eval','compile','__import__','getattr','setattr'}
 vm=methods(tree)
 for name in helper_names:
  assert dump(next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name==name))==dump(next(n for n in base.body if isinstance(n,ast.ClassDef) and n.name==name))
 if v['role']=='control':
  assert src==(w/'history_g2_r0069_summary_global.py').read_text()
 else:
  assert set(vm)==set(bm)
  for name in vm:
   if name=='__init__': assert dump(StripNewInit().visit(copy.deepcopy(vm[name])))==dump(bm[name]), name
   elif name in ('_pool','_target_match_summary'):
    assert dump(Train().visit(copy.deepcopy(vm[name])))==dump(Train().visit(copy.deepcopy(bm[name]))),name
   else: assert dump(vm[name])==dump(bm[name]),name
  arg_names={a.arg for a in vm['__init__'].args.args}
  assert set(cfg)<=arg_names
 # Keep file/source identities in the submitted receipt notes.
 digest=hashlib.sha256(src.encode()).hexdigest()
 print(v['name'],digest,'syntax/config/import/training-AST checks passed')
 v['note']+=' Source SHA256='+digest+'.'
# Symbolic exact-integer indexing checks are not tensor/numerical runtime tests.
for B,V in [(1,1),(2,4),(3,7)]:
 coeff=[[[[1000*b+100*s+10*g+e for e in range(10)] for g in range(10)] for s in range(5)] for b in range(B)]
 # Parent [B,g,s,e] storage, followed by transpose to [B,s,g,e].
 native=[[[coeff[b][s][g][e] for g in range(10) for e in range(10)] for s in range(5)] for b in range(B)]
 direct=[[sum(coeff[b][s],[]) for s in range(5)] for b in range(B)]
 assert native==direct
 values=[[[b*17+g*5+s*3+v-9 for v in range(V)] for s in range(3)] for b in range(B) for g in range(10)]
 # Explicit scalar weighted materialize+sum versus each stratum dot product.
 for b in range(B):
  weights=[[b+g-2*s for s in range(3)] for g in range(10)]
  original=[[sum(weights[g][s]*values[b*10+g][s][v] for g in range(10)) for v in range(V)] for s in range(3)]
  replacement=[]
  for s in range(3):
   replacement.append([sum(weights[g][s]*values[b*10+g][s][v] for g in range(10)) for v in range(V)])
  assert original==replacement
# Resource arithmetic: units + preparation + both reserves fit recorded remainder.
assert 4*r['context']['protocol']['trial_cap_seconds']+600+6000+6000<r['context']['remaining_seconds']
assert hashlib.sha256((w/'baseline_reference.py').read_bytes()).hexdigest()==r['context']['protocol']['source_sha256']['baseline.py']
for h in r['context']['history']:
 if h['id']==p['parent_trial']: assert hashlib.sha256((w/'layout_reference.py').read_bytes()).hexdigest()==h['source_sha256']
summary=' Completed local verification: recursive study-schema/phase/protocol/evidence/parent and all15 inherited knowledge-assessment coverage; four standalone syntax/import/config checks; byte-identical global control and baseline hashes; helper classes and every unchanged Model method AST-identical; deleting only new constructor validation/attributes/options reproduces parent initialization AST; training=True branch specialization reproduces both changed methods exactly; pure-Python integer indexing checks for direct layout and stratum contraction; conservative cost/reserve arithmetic. These are static/symbolic checks, not PyTorch execution or measured performance. Host runtime numerical checks remain required.'
for v in p['variants']: v['note']+=summary
(w/'proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
print('PASS: study schema, protocol, evidence, coverage, source boundaries, training AST, indexing and budget; host execution pending')
